import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import useQuiz from '../hooks/useQuiz';
import Button from '../components/common/Button';
import QuizQuestion from '../components/quiz/QuizQuestion';
import QuizOption from '../components/quiz/QuizOption';
import LoadingAnimation from '../components/common/LoadingAnimation';
import { fetchQuiz, submitQuizAnswers } from '../services/api/quizApi';
import { QuizQuestion as QuizQuestionType } from '../types/quizTypes';

const QuizPage: React.FC = () => {
  const { quizType } = useParams<{ quizType: string }>();
  const navigate = useNavigate();
  const [questions, setQuestions] = useState<QuizQuestionType[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const {
    currentQuestion,
    currentQuestionIndex,
    answers,
    progress,
    selectOption,
    goToNextQuestion,
    goToPreviousQuestion,
    isCompleted
  } = useQuiz({
    quizType: quizType || '',
    questions
  });

  // Quiz verilerini yükleme
  useEffect(() => {
    const loadQuizData = async () => {
      try {
        setLoading(true);
        setError(null);

        if (!quizType) {
          throw new Error('Quiz tipi belirtilmedi');
        }

        const quizData = await fetchQuiz(quizType);
        setQuestions(quizData);
      } catch (err) {
        console.error('Quiz verileri yüklenirken hata oluştu:', err);
        setError('Quiz verilerini yüklerken bir hata oluştu. Lütfen daha sonra tekrar deneyin.');
      } finally {
        setLoading(false);
      }
    };

    loadQuizData();
  }, [quizType]);

  // Quiz tamamlandığında
  const handleQuizComplete = async () => {
    if (!quizType) return;

    try {
      setSubmitting(true);

      const response = await submitQuizAnswers({
        quizType,
        answers
      });

      // Sonuç sayfasına yönlendir
      navigate(`/results/${quizType}`, { 
        state: { 
          quizResult: response,
          answers
        } 
      });
    } catch (err) {
      console.error('Quiz yanıtları gönderilirken hata oluştu:', err);
      setError('Yanıtlarınız gönderilirken bir hata oluştu. Lütfen daha sonra tekrar deneyin.');
      setSubmitting(false);
    }
  };

  // Seçeneğe tıklama işleyicisi
  const handleOptionClick = (optionId: string) => {
    if (submitting) return;
    selectOption(optionId);
  };

  // İleri butonu işleyicisi
  const handleNextClick = () => {
    if (isCompleted) {
      handleQuizComplete();
    } else {
      goToNextQuestion();
    }
  };

  // Yükleme durumu
  if (loading) {
    return (
      <div className="quiz-container">
        <LoadingAnimation text="Quiz yükleniyor..." />
      </div>
    );
  }

  // Hata durumu
  if (error) {
    return (
      <div className="quiz-container">
        <div className="quiz-error">
          <h2>Hata</h2>
          <p>{error}</p>
          <Button onClick={() => navigate('/quiz-selection')}>
            Quiz Seçimine Dön
          </Button>
        </div>
      </div>
    );
  }

  // Quiz içeriği
  return (
    <div className="quiz-container">
      <motion.div
        className="quiz-content"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -20 }}
        transition={{ duration: 0.5 }}
      >
        {currentQuestion && (
          <>
            <QuizQuestion
              question={currentQuestion.question}
              questionNumber={currentQuestionIndex + 1}
              totalQuestions={questions.length}
            />

            <div className="progress-bar">
              <div 
                className="progress-bar-inner" 
                style={{ width: `${progress}%` }}
              ></div>
            </div>

            <div className="quiz-options">
              {currentQuestion.options.map((option) => (
                <QuizOption
                  key={option.id}
                  id={option.id}
                  text={option.text}
                  selected={answers.some(a => a.questionId === currentQuestion.id && a.selectedOptionId === option.id)}
                  onSelect={handleOptionClick}
                />
              ))}
            </div>

            <div className="quiz-controls">
              <Button 
                onClick={goToPreviousQuestion}
                disabled={currentQuestionIndex === 0 || submitting}
                className="quiz-prev-btn"
              >
                Geri
              </Button>

              <Button
                onClick={handleNextClick}
                disabled={!answers.some(a => a.questionId === currentQuestion.id) || submitting}
                className="quiz-next-btn"
              >
                {isCompleted ? (submitting ? 'Gönderiliyor...' : 'Sonuçları Gör') : 'İleri'}
              </Button>
            </div>
          </>
        )}
      </motion.div>
    </div>
  );
};

export default QuizPage;

