                  id={option.id}
                  text={option.text}
                  selected={answers.some(a => a.questionId === currentQuestion.id && a.selectedOptionId === option.id)}
                  onSelect={handleOptionClick}
                />
              ))}
            </div>

            <div className="quiz-controls">
              <Button 
                onClick={goToPreviousQuestion}
                disabled={currentQuestionIndex === 0 || submitting}
                className="quiz-prev-btn"
              >
                Geri
              </Button>

              <Button
                onClick={handleNextClick}
                disabled={!answers.some(a => a.questionId === currentQuestion.id) || submitting}
                className="quiz-next-btn"
              >
                {isCompleted ? (submitting ? 'Gönderiliyor...' : 'Sonuçları Gör') : 'İleri'}
              </Button>
            </div>
          </>
        )}
      </motion.div>
    </div>
  );
};

export default Quiz;
